// Standard syntax
let sorted = names.sorted(by: { a, b in a < b })

// Trailing closure — cleaner
let sorted2 = names.sorted { a, b in a < b }

// Only argument — drop parentheses
let doubled = numbers.map { $0 * 2 }

// Multi-line trailing closure
let results = items.filter {
    $0.isActive && $0.score > 80
}

// Multiple trailing closures (Swift 5.3+)
Button {
    viewModel.submit()
} label: {
    Text("Submit")
}

class DataLoader {
    var data: [String] = []

    func load() {
        // ❌ Retain cycle — closure captures self strongly
        // networkService.fetch { result in
        //     self.data = result
        // }

        // ✅ Weak self breaks the cycle
        networkService.fetch { [weak self] result in
            guard let self else { return }
            self.data = result
        }
    }

    // ✅ Non-escaping — no capture list needed
    func process() {
        data.forEach { item in
            print(item)  // no retain cycle risk
        }
    }
}

// Non-escaping (default) — called immediately
func apply(_ transform: (Int) -> Int, to value: Int) -> Int {
    return transform(value)
}
let result = apply({ $0 * 2 }, to: 5) // 10

// Escaping — stored for later
class EventBus {
    var handlers: [() -> Void] = []

    func onEvent(_ handler: @escaping () -> Void) {
        handlers.append(handler)  // stored beyond function
    }

    func fire() {
        handlers.forEach { $0() }
    }
}

// Escaping requires explicit 'self'
class Timer {
    var tick: (() -> Void)?
    func start() {
        tick = { [weak self] in
            self?.update()  // explicit self required
        }
    }
}
